		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, ownerKey)).isNull();
		long validDependency = validDependency(kind);
		assertThat(validDependency).isPositive();
		assertThat(ValueIds.getIdType(validDependency)).isEqualTo(kind.dependencyType);
		byte[] valid = payload(kind, LmdbCompatibilityFixtures.unsigned(validDependency));
		LmdbCompatibilityFixtures.nativePut(directory, null, ownerKey, valid);
		assertNoReverseOwner(owner, valid);
		// Orphan physical owner records are legitimate; only the replacement dependency is corrupt.
		verifyWithoutMutation();
		long invalidDependency = Long.MIN_VALUE | (long) kind.dependencyType << 1;
		assertThat(invalidDependency).isNegative();
		assertThat(ValueIds.isInlined(invalidDependency)).isFalse();
		assertThat(ValueIds.getIdType(invalidDependency)).isEqualTo(kind.dependencyType);
		byte[] corrupt = payload(kind, upperHalf(invalidDependency));
		LmdbCompatibilityFixtures.nativePut(directory, null, ownerKey, corrupt);
		assertNoReverseOwner(owner, corrupt);
		for (int attempt = 0; attempt < 2; attempt++) {
			assertVerificationRejectedWithoutMutation("ValueStore owner has an invalid forward dependency");
			assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, ownerKey)).containsExactly(corrupt);
		}
