	private long validDependency(OwnerKind kind) throws IOException {
		if (kind == OwnerKind.LITERAL) {
			return LmdbCompatibilityFixtures.findReferenceId(directory, ValueIds.T_URI,
					"label".getBytes(StandardCharsets.UTF_8));
		}
		long subject = LmdbCompatibilityFixtures.findReferenceId(directory, ValueIds.T_URI,
				"subject".getBytes(StandardCharsets.UTF_8));
		byte[] encoded = LmdbCompatibilityFixtures.nativeGet(directory, null,
				LmdbCompatibilityFixtures.idKey(subject));
		assertThat(encoded).isNotNull();
		ByteBuffer payload = ByteBuffer.wrap(encoded);
		assertThat(payload.get()).isEqualTo((byte) 0);
		return Varint.readUnsigned(payload);
	}

	private static byte[] payload(OwnerKind kind, byte[] dependency) {
		ByteBuffer result = ByteBuffer.allocate(32);
		result.put(kind.payloadType).put(dependency);
		if (kind == OwnerKind.LITERAL) {
			result.put((byte) 0); // no language tag or direction
		}
		result.put("orphan".getBytes(StandardCharsets.UTF_8));
		return Arrays.copyOf(result.array(), result.position());
	}

	private void assertNoReverseOwner(long owner, byte[] payload) throws IOException {
		byte[] ownerKey = LmdbCompatibilityFixtures.idKey(owner);
		if (payload.length <= 16) {
			assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, payload)).isNull();
			return;
		}
		CRC32 crc = new CRC32();
		crc.update(payload);
		byte[] encodedHash = LmdbCompatibilityFixtures.unsigned(crc.getValue());
		byte[] hashKey = ByteBuffer.allocate(1 + encodedHash.length).put((byte) 6).put(encodedHash).array();
		byte[] collisionKey = ByteBuffer.allocate(1 + encodedHash.length + ownerKey.length)
				.put((byte) 7)
				.put(encodedHash)
				.put(ownerKey)
				.array();
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, hashKey)).isNotEqualTo(ownerKey);
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, null, collisionKey)).isNull();
	}

	private static byte[] upperHalf(long value) {
		assertThat(value).isNegative();
		// Independent bytes: the ordinary encoder must not decide whether the corruption is well-formed.
		byte[] encoded = ByteBuffer.allocate(9).put((byte) 0xff).putLong(value).array();
		ByteBuffer decoded = ByteBuffer.wrap(encoded);
		assertThat(Varint.readUnsigned(decoded)).isEqualTo(value);
		assertThat(decoded.hasRemaining()).isFalse();
		ByteBuffer scalar = ByteBuffer.allocate(9);
		Varint.writeUnsigned(scalar, value);
		assertThat(scalar.position()).isEqualTo(9);
		assertThat(scalar.array()).containsExactly(encoded);
		ByteBuffer list = ByteBuffer.allocate(9);
		Varint.writeListUnsigned(list, new long[] { value });
		assertThat(list.position()).isEqualTo(9);
		assertThat(list.array()).containsExactly(encoded);
		return encoded;
	}

